import inspect

class Base:
    def __init__(self, a, b=1):
        print(f"Base init called with a={a}, b={b}")

class Sub(Base):
    def __init__(self, c):
        print(f"Sub init called with c={c}")
        super().__init__(c + 1)

class Sub2(Base):
     def __init__(self, a, b=2):
        print(f"Sub2 init called with a={a}, b={b}")
        super().__init__(a, b)

def call_init(cls, lock_file, timeout=1):
    all_params = {
        "lock_file": lock_file,
        "timeout": timeout,
    }
    present_params = set(inspect.signature(cls.__init__).parameters)
    print(f"{cls.__name__} present_params: {present_params}")
    init_params = {key: value for key, value in all_params.items() if key in present_params}

    # Current logic:
    # init_params["lock_file"] = lock_file
    # instance = cls(**init_params)

    # Proposed logic:
    if "lock_file" in present_params:
        instance = cls(**init_params)
    else:
        # Assume first parameter is lock_file
        params = list(inspect.signature(cls.__init__).parameters.values())
        if len(params) > 1: # params[0] is self
             first_param_name = params[1].name
             print(f"Mapping lock_file to {first_param_name}")
             init_params[first_param_name] = lock_file

        # remove lock_file from init_params if it was added by filtering but not present in subclass
        # wait, filtering already handles that.

        instance = cls(**init_params)
    return instance

